/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { ArrayContraction, ArrayTensorProduct, MatrixSymbol, Sym, convertArrayToMatrix } from '../../../../src';
import { sympyStr } from '../../../sympy-str';

describe("doctests of sympy.tensor.array.expressions.from_array_to_matrix", () => {
  it("convert_array_to_matrix(cg)", () => {
    const N = new Sym('N');
    expect(sympyStr(convertArrayToMatrix(new ArrayContraction(new ArrayTensorProduct(new MatrixSymbol('A', N, N), new MatrixSymbol('B', N, N)), [1, 2])))).toBe('A*B');
  });
  it("convert_array_to_matrix(cg) (2)", () => {
    const N = new Sym('N');
    expect(sympyStr(convertArrayToMatrix(new ArrayContraction(new ArrayTensorProduct(new MatrixSymbol('B', N, N), new MatrixSymbol('A', N, N)), [0, 3])))).toBe('B.T*A.T');
  });
  it("convert_array_to_matrix(cg) (3)", () => {
    const N = new Sym('N');
    expect(sympyStr(convertArrayToMatrix(new ArrayContraction(new ArrayTensorProduct(new MatrixSymbol('A', N, N), new MatrixSymbol('B', N, N)), [0, 2])))).toBe('A.T*B');
  });
  it("convert_array_to_matrix(cg) (4)", () => {
    const N = new Sym('N');
    expect(sympyStr(convertArrayToMatrix(new ArrayContraction(new ArrayTensorProduct(new MatrixSymbol('B', N, N), new MatrixSymbol('A', N, N)), [0, 2])))).toBe('B.T*A');
  });
  it("convert_array_to_matrix(cg) (5)", () => {
    const N = new Sym('N');
    expect(sympyStr(convertArrayToMatrix(new ArrayContraction(new MatrixSymbol('A', N, N), [0, 1])))).toBe('Trace(A)');
  });
  it("convert_array_to_matrix(cg) (6)", () => {
    const N = new Sym('N');
    expect(sympyStr(convertArrayToMatrix(new ArrayContraction(new ArrayTensorProduct(new MatrixSymbol('A', N, N), new MatrixSymbol('B', N, N)), [0, 3], [1, 2])))).toBe('Trace(A*B)');
  });
  it("convert_array_to_matrix(cg) (7)", () => {
    const N = new Sym('N');
    expect(sympyStr(convertArrayToMatrix(new ArrayContraction(new ArrayTensorProduct(new MatrixSymbol('B', N, N), new MatrixSymbol('A', N, N), new MatrixSymbol('A', N, N)), [0, 5], [1, 3])))).toBe('A*B.T*A.T');
  });
  it("convert_array_to_matrix(cg) (8)", () => {
    const N = new Sym('N');
    expect(sympyStr(convertArrayToMatrix(new ArrayContraction(new ArrayTensorProduct(new MatrixSymbol('A', N, N), new MatrixSymbol('B', N, N)), [1, 2])))).toBe('A*B');
  });
  it("convert_array_to_matrix(cg) (9)", () => {
    const N = new Sym('N');
    expect(sympyStr(convertArrayToMatrix(new ArrayContraction(new ArrayTensorProduct(new MatrixSymbol('A', N, N), new MatrixSymbol('B', N, N), new MatrixSymbol('C', N, N), new MatrixSymbol('D', N, N)), [1, 2], [5, 6])))).toBe('ArrayTensorProduct(A*B, C*D)');
  });
});
